use rtla::ast::Module;
use std::collections::HashSet;
use std::path::{Path, PathBuf};

pub fn with_suffix(file: &str, suffix: &str) -> PathBuf {
    if file.ends_with(suffix) {
        file.into()
    } else {
        format!("{file}{suffix}").into()
    }
}

// WASI starts without a host working directory. The npm launcher supplies its guest path.
pub fn from_cwd(path: &Path) -> PathBuf {
    #[cfg(target_os = "wasi")]
    if let Some(cwd) = std::env::var_os("IDEALIS_CWD") {
        return PathBuf::from(cwd).join(path);
    }
    path.to_owned()
}

fn read_module(path: &Path, verbose: bool) -> Result<Module, String> {
    if verbose {
        println!("Parsing file {}", path.display());
    }
    let source = std::fs::read_to_string(path).map_err(|e| format!("{}: {e}", path.display()))?;
    let module = rtla::parse_module(&source).map_err(|e| format!("{}: {e}", path.display()))?;
    if path.file_stem() != Some(module.name.as_ref()) {
        return Err(format!(
            "{}: module name {} differs from file name",
            path.display(),
            module.name
        ));
    }
    Ok(module)
}

pub struct Bundle {
    pub root: Module,
    pub dependencies: Vec<Module>,
}

impl Bundle {
    pub fn load(path: &Path, verbose: bool) -> Result<Self, String> {
        let root = read_module(path, verbose)?;
        let dir = path.parent().unwrap_or(Path::new("."));
        let mut dependencies = Vec::new();
        let mut loaded = HashSet::new();
        let mut visiting = HashSet::new();
        visit(
            &root,
            dir,
            verbose,
            &mut visiting,
            &mut loaded,
            &mut dependencies,
        )?;
        Ok(Self { root, dependencies })
    }
}

fn visit(
    module: &Module,
    dir: &Path,
    verbose: bool,
    visiting: &mut HashSet<String>,
    loaded: &mut HashSet<String>,
    dependencies: &mut Vec<Module>,
) -> Result<(), String> {
    if !visiting.insert(module.name.clone()) {
        return Err(format!("Cyclic module import: {}", module.name));
    }
    if visiting.len() > 40 || loaded.len() >= 256 {
        return Err("Module bundle exceeds the frontend limit".into());
    }
    for name in module
        .extends
        .iter()
        .chain(module.instances.iter().map(|instance| &instance.module))
    {
        if loaded.contains(name) {
            continue;
        }
        let path = dir.join(format!("{name}.tla"));
        if matches!(
            name.as_str(),
            "Naturals" | "Integers" | "Sequences" | "FiniteSets" | "TLC"
        ) {
            if path.exists() {
                return Err(format!(
                    "Unsupported local override of standard module {name}"
                ));
            }
            continue;
        }
        let child = read_module(&path, verbose)?;
        visit(&child, dir, verbose, visiting, loaded, dependencies)?;
        dependencies.push(child);
    }
    visiting.remove(&module.name);
    loaded.insert(module.name.clone());
    Ok(())
}

use rtlc::{Value, ir::SafetyViolation};

fn values(items: &[Value]) -> String {
    items.iter().map(render).collect::<Vec<_>>().join(", ")
}

fn record_name(name: &str) -> bool {
    name.chars().all(|c| c == '_' || c.is_alphanumeric())
        && name.chars().any(char::is_alphabetic)
        && !(name.len() > 3 && (name.starts_with("WF_") || name.starts_with("SF_")))
}

fn render(value: &Value) -> String {
    match value {
        Value::Bool(true) => "TRUE".into(),
        Value::Bool(false) => "FALSE".into(),
        Value::Int(n) | Value::ModelValue(n) => n.clone(),
        Value::String(s) => serde_json::to_string(s).expect("serializable string"),
        Value::Set(items) => format!("{{{}}}", values(items)),
        Value::List(items) => format!("<<{}>>", values(items)),
        Value::Record(fields) if !fields.iter().all(|(name, _)| record_name(name)) => {
            let entries = fields
                .iter()
                .map(|(name, v)| {
                    let key = serde_json::to_string(name).expect("serializable string key");
                    format!("{key} :> {}", render(v))
                })
                .collect::<Vec<_>>();
            format!("({})", entries.join(" @@ "))
        }
        Value::Record(fields) => {
            let entries = fields
                .iter()
                .map(|(name, v)| format!("{name} |-> {}", render(v)))
                .collect::<Vec<_>>();
            format!("[{}]", entries.join(", "))
        }
        Value::Map(entries) => {
            let entries = entries
                .iter()
                .map(|(k, v)| format!("{} :> {}", render(k), render(v)))
                .collect::<Vec<_>>();
            format!("({})", entries.join(" @@ "))
        }
        // Portable-only values; the TLA evaluator never produces them.
        Value::Null | Value::Bytes(_) => serde_json::to_string(value).expect("serializable value"),
    }
}

pub fn print_diff(variables: &[String], violation: &SafetyViolation, status: &str) {
    let steps = &violation.trace;
    let prefix = if variables.len() == 1 { "" } else { "/\\ " };
    for (index, step) in steps.iter().enumerate() {
        let label = step.action.as_deref().unwrap_or("Initial predicate");
        if !(status == "invariant-violation" && steps.len() == 1) {
            println!("State {}: <{label}>", index + 1);
        }
        // TLCTrace prints the final safety state in full except for a successor
        // of the initial state. A lasso keeps predecessor-relative diffs.
        let full_final = violation.loop_start.is_none()
            && index + 1 == steps.len()
            && (status == "deadlock" || index > 1);
        for (slot, (name, value)) in variables.iter().zip(&step.values).enumerate() {
            if index == 0 || full_final || steps[index - 1].values[slot] != *value {
                println!("{prefix}{name} = {}", render(value));
            }
        }
        println!();
    }
    if let Some(start) = violation.loop_start {
        let action = violation.loop_action.as_deref().unwrap_or_default();
        if start + 1 == steps.len() {
            println!("State {}: Stuttering", steps.len() + 1);
        } else {
            println!("Back to state {}: {action}", start + 1);
        }
    }
}

use std::process::Command;

fn run(args: &[&str], code: i32, message: &str) -> String {
    let output = Command::new(env!("CARGO_BIN_EXE_idealis"))
        .current_dir(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/specs"))
        .args(args)
        .output()
        .unwrap();
    let text = format!(
        "{}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(output.status.code(), Some(code), "{text}");
    assert!(text.contains(message), "{text}");
    text
}
#[test]
fn finite_tlc_checks_the_selected_configuration() {
    run(
        &["tlc", "-workers", "1", "Counter"],
        0,
        "No error has been found",
    );
    run(&["tlc", "Counter.tla", "-config", "Bad"], 12, "Broken");
    run(&["tlc", "-simulate", "Counter"], 1, "-simulate");
}
#[test]
fn sany_distinguishes_parsing_and_semantics() {
    run(
        &["tla", "Counter"],
        0,
        "Semantic processing of module Counter",
    );
    run(&["tla", "Unknown.tla"], 0, "Unknown operator: `Missing'.");
    run(&["tla", "-s", "Unknown.tla"], 0, "Parsing file");
    run(&["tla", "-d", "Counter"], 255, "-d");
}

#[test]
fn checks_local_imports_and_deadlock_switch() {
    run(&["tlc", "Stop"], 11, "Deadlock reached.");
    run(&["tlc", "-deadlock", "Stop"], 0, "No error has been found");
    run(&["tla", "Stop"], 0, "Semantic processing of module Stop");
}

#[test]
fn incomplete_search_never_reports_success() {
    run(
        &["tlc", "-config", "Bound", "Counter"],
        255,
        "bounded (depth)",
    );
    run(&["tlc", "-config", "Empty", "Counter"], 255, "empty");
    run(&["tlc", "MissingModel"], 255, "MissingModel.cfg");
}

#[test]
fn lowering_cannot_discard_an_unchecked_theorem() {
    run(&["tlc", "-config", "Stop", "Proof"], 150, "proofs");
    run(&["tla", "Proof"], 255, "proofs");
    run(&["tla", "-s", "Proof"], 0, "Parsing file");
}

#[test]
fn tlc_prints_difftrace_with_full_error_state() {
    let report = run(
        &[
            "tlc",
            "-modelcheck",
            "-workers",
            "auto",
            "-difftrace",
            "Diff",
        ],
        12,
        "State 3:",
    );
    assert_eq!(report.matches("stable = \"constant\"").count(), 2);
    let middle = report
        .split_once("State 2:")
        .unwrap()
        .1
        .split_once("State 3:")
        .unwrap()
        .0;
    assert!(middle.contains("x = 1"));
    assert!(!middle.contains("stable"));
    run(&["tlc", "-h"], 1, "-difftrace");
}

#[test]
fn sany_reports_level_diagnostics_and_honors_the_level_switch() {
    run(&["tla", "-stat", "Level"], 0, "Semantic errors:");
    let output = run(&["tla", "-l", "Level"], 0, "Semantic processing");
    assert!(!output.contains("Semantic errors:"));
}

#[test]
fn false_constant_checks_are_configuration_errors() {
    for cfg in ["Rejected", "Property"] {
        run(&["tlc", "-config", cfg, "Values"], 151, "is equal to FALSE");
    }
}

